'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const initial={points:128450,earned:0,energy:4500,power:8,capacity:5000,speed:5,levels:[3,1,1],taps:0,runs:0,claimed:[],name:'Nexus-01',logs:[]};
let state;
try {const saved=JSON.parse(localStorage.getItem('taptap-v1'));state={...initial,...saved};if(!Number.isFinite(state.points)||!Array.isArray(state.levels))state={...initial};}catch{state={...initial};}
let running=false,runTaps=0,targetTaps=100,runGain=0,interval=null,toastTimer=null;
const upgrades=[{name:'Multitap',desc:'More points with every tap',long:'Increase your agent’s earning power by 2 TAP on every tap.',icon:'i-bolt',base:1500},{name:'Energy tank',desc:'A bigger tank. Longer runs.',long:'Add 1,000 energy capacity so your agent can keep working longer.',icon:'i-shield',base:2500},{name:'Agent overclock',desc:'Faster taps. Same intelligence.',long:'Add 2 taps per second to complete your commands faster.',icon:'i-agent',base:4000}];
const fmt=n=>Math.floor(n).toLocaleString('en-US');
const icon=id=>`<svg aria-hidden="true"><use href="#${id}"/></svg>`;
const cost=i=>Math.floor(upgrades[i].base*Math.pow(1.65,state.levels[i]-(i===0?3:1)));
function save(){try{localStorage.setItem('taptap-v1',JSON.stringify(state));}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function showModal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function modalContent(title,body,iconId='i-agent'){return `<div class="modal-icon">${icon(iconId)}</div><h2>${title}</h2>${body}`;}
function addLog(title,detail,value,type='i-bolt'){state.logs.unshift({title,detail,value,type});state.logs=state.logs.slice(0,8);renderLogs();save();}
function renderLogs(){const list=state.logs.length?state.logs:[{title:'Your agent is ready',detail:'Send a prompt to start your first run',value:'Let’s go ↗',type:'i-agent'},{title:'Demo arena initialized',detail:'Energy is recharging automatically',value:'+5 / sec',type:'i-bolt'},{title:'Genesis profile created',detail:'Demo identity · no live verification',value:'READY',type:'i-shield'}];$('#activity-list').replaceChildren(...list.slice(0,3).map(l=>{const row=document.createElement('div');row.className='activity-item';row.innerHTML=`<span class="activity-icon">${icon(l.type)}</span><div><h4></h4><p></p></div><span class="activity-value"></span>`;row.querySelector('h4').textContent=l.title;row.querySelector('p').textContent=l.detail;row.querySelector('.activity-value').textContent=l.value;return row;}));}
function render(){
$('#total-points').innerHTML=`${fmt(state.points)}<span>TAP</span>`;$('#earned-today').textContent='+'+fmt(state.earned);$('#tap-power').textContent=state.power;$('#power-level').textContent='LVL '+state.levels[0];$('#energy-count').innerHTML=`${fmt(state.energy)} <span>/ ${fmt(state.capacity)}</span>`;$('#energy-bar').style.width=(state.energy/state.capacity*100)+'%';$('#agent-name').replaceChildren(document.createTextNode(state.name+' '),Object.assign(document.createElement('span'),{className:'verified',textContent:'✓'}));$('#wallet-total').innerHTML=`${fmt(state.points)} <small>TAP</small>`;
$$('.floating-point').forEach(x=>x.textContent='+'+state.power);
$('#mini-upgrades').innerHTML=upgrades.slice(0,2).map((u,i)=>`<div class="upgrade-row"><span class="upgrade-icon">${icon(u.icon)}</span><div><h3>${u.name} <span class="upgrade-level">LVL ${state.levels[i]}</span></h3><p>${u.desc}</p></div><button class="upgrade-price" data-upgrade="${i}" aria-label="Upgrade ${u.name} for ${fmt(cost(i))} TAP">${icon('i-coin').replace('<svg ','<svg style="width:11px;height:11px" ')} ${fmt(cost(i))} <span>+</span></button></div>`).join('');
$('#full-upgrades').innerHTML=upgrades.map((u,i)=>`<article class="upgrade-panel"><div class="upgrade-icon">${icon(u.icon)}</div><span class="level-tag">LEVEL ${state.levels[i]}</span><h3>${u.name}</h3><p>${u.long}</p><button class="run-button" data-upgrade="${i}">Upgrade · ${fmt(cost(i))} TAP ${icon('i-arrow')}</button></article>`).join('');renderMissions();renderLeaderboard();
}
function upgrade(i){if(running){toast('Finish or pause your agent run before upgrading.');return;}const price=cost(i);if(state.points<price){toast(`You need ${fmt(price-state.points)} more TAP for this upgrade.`);return;}state.points-=price;state.levels[i]++;if(i===0)state.power+=2;if(i===1){state.capacity+=1000;state.energy+=1000;}if(i===2)state.speed+=2;addLog(upgrades[i].name+' upgraded','Now level '+state.levels[i],'-'+fmt(price),'i-bolt');render();save();toast(upgrades[i].name+' is now level '+state.levels[i]+'.');}
const missions=[{name:'First command',desc:'Complete one agent run.',goal:1,reward:500,metric:()=>state.runs},{name:'A thousand tiny taps',desc:'Let your agent complete 1,000 taps.',goal:1000,reward:2500,metric:()=>state.taps},{name:'Power moves',desc:'Upgrade Multitap to level 5.',goal:5,reward:1500,metric:()=>state.levels[0]}];
function renderMissions(){$('#mission-list').innerHTML=missions.map((m,i)=>{const progress=Math.min(m.goal,m.metric()),claimed=state.claimed.includes(i);return `<article class="mission-card"><span class="upgrade-icon">${icon('i-task')}</span><div class="mission-copy"><h3>${m.name}</h3><p>${m.desc} ${fmt(progress)} / ${fmt(m.goal)}</p><div class="energy-track"><div style="width:${progress/m.goal*100}%"></div></div></div><span class="positive">+${fmt(m.reward)} TAP</span><button class="run-button" data-claim="${i}" ${claimed||progress<m.goal?'disabled':''}>${claimed?'Claimed ✓':progress>=m.goal?'Claim reward':'In progress'}</button></article>`;}).join('');}
function claimMission(i){const m=missions[i];if(state.claimed.includes(i)||m.metric()<m.goal)return;state.claimed.push(i);state.points+=m.reward;state.earned+=m.reward;addLog('Mission complete: '+m.name,'Reward added to your demo balance','+'+fmt(m.reward),'i-task');render();save();toast('Mission reward claimed: +'+fmt(m.reward)+' TAP.');}
function renderLeaderboard(){const rows=[['01','Alpha-7','Diamond',9854320],['02','BNB.Brain','Diamond',8240100],['03','Satoshi.exe','Platinum',6178420],['04','ByteRunner','Platinum',4235700]];$('#leaderboard-body').innerHTML=rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]} <span class="verified">✓</span></td><td>${r[2]}</td><td>${fmt(r[3])}</td></tr>`).join('');const tr=document.createElement('tr');tr.className='you';tr.innerHTML=`<td>482</td><td></td><td>Gold</td><td>${fmt(state.points)}</td>`;tr.children[1].textContent=state.name+' · You';$('#leaderboard-body').append(tr);}
function switchView(view){if(!['arena','upgrades','missions','leaderboard','wallet'].includes(view))view='arena';$$('.view').forEach(el=>el.classList.toggle('active',el.id===view+'-view'));$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#breadcrumb').textContent=view==='arena'?'Overview':view[0].toUpperCase()+view.slice(1);history.replaceState(null,'','#'+view);window.scrollTo({top:0,behavior:'smooth'});}
function parsePrompt(prompt){const normalized=prompt.trim().toLowerCase();if(!normalized||!/(tap|energy|power|collect|earn|start|farm)/.test(normalized))return null;const match=normalized.match(/\d[\d,]*/),number=match?parseInt(match[0].replaceAll(',',''),10):100;if(!number||number<1)return null;return Math.min(10000,/energy/.test(normalized)?number:number);}
function toggleRun(){if(running){finishRun(false);return;}const target=parsePrompt($('#prompt').value);if(!target){toast('Try a command like “Tap 100 times” or “Use 500 energy”.');$('#prompt').focus();return;}if(state.energy<1){toast('Your agent needs energy. It recharges at 5 per second.');return;}targetTaps=target;runTaps=0;runGain=0;running=true;$('#arena-stage').classList.add('running');$('#run-agent').innerHTML=`${icon('i-bolt')}<span>Pause agent</span><span>Ⅱ</span>`;$('#arena-status').textContent='Agent is tapping';$('#command-note').textContent=`Executing ${fmt(targetTaps)} taps · ${state.speed} taps/sec`;addLog('Command accepted',`Demo agent queued ${fmt(targetTaps)} taps`,'RUNNING','i-code');interval=setInterval(tick,200);}
let fractionalTaps=0;
function tick(){fractionalTaps+=state.speed/5;const amount=Math.min(Math.floor(fractionalTaps),targetTaps-runTaps,Math.floor(state.energy));if(amount<1){if(state.energy<1)finishRun(false,'Energy depleted');return;}fractionalTaps-=amount;runTaps+=amount;const gain=amount*state.power;runGain+=gain;state.points+=gain;state.earned+=gain;state.taps+=amount;state.energy-=amount;$('#arena-status').textContent=`${fmt(runTaps)} / ${fmt(targetTaps)} taps`;$('#command-note').textContent=`Agent running · +${fmt(runGain)} TAP earned`;render();if(runTaps>=targetTaps)finishRun(true);}
function finishRun(completed,reason){clearInterval(interval);interval=null;running=false;fractionalTaps=0;if(completed)state.runs++;$('#arena-stage').classList.remove('running');$('#run-agent').innerHTML=`${icon('i-bolt')}<span>Run agent</span><svg class="arrow"><use href="#i-arrow"/></svg>`;$('#arena-status').textContent=completed?'Command complete. Nice work.':reason||'Agent paused';$('#command-note').textContent=`${fmt(runTaps)} taps completed · +${fmt(runGain)} TAP`;addLog(completed?'Agent run complete':reason||'Agent run paused',`${fmt(runTaps)} taps · ${state.power} TAP per tap`,'+'+fmt(runGain));render();save();if(completed)toast(`Command complete: ${fmt(runTaps)} taps earned ${fmt(runGain)} TAP.`);}
function agentModal(){showModal(modalContent('Meet your demo agent.',`<p>Your agent runs commands in this browser demo. Real Binance Agent ID verification and wallet signing are not connected.</p><label for="agent-input">Agent display name</label><input id="agent-input" maxlength="24" autocomplete="off"><p class="modal-note">Demo ID: DEMO-00482. No real wallet or Binance account is connected. Never enter a private key or seed phrase here.</p><button class="run-button" id="save-agent">Save demo agent ${icon('i-arrow')}</button>`));$('#agent-input').value=state.name;$('#save-agent').onclick=()=>{const name=$('#agent-input').value.trim();if(!name){$('#agent-input').focus();return;}state.name=name;render();save();$('#modal').close();toast('Demo agent updated. Ready for your next command.');};}
function about(){showModal(modalContent('The agent era starts here.',`<p>TapTap is an independent, interactive concept for an agent-only tap-to-earn game on BNB Chain. This version uses a local agent simulation and saves progress in your browser.</p><p>Live play requires a backend that verifies Binance agent identities, authenticates signed agent commands, and enforces server-side points and energy. Token contracts and conversion terms are not deployed.</p><p class="modal-note">All points, wallets, identities, leagues and rankings shown here are demo data. No Binance affiliation or endorsement is claimed.</p><button class="run-button" data-close>Got it ${icon('i-arrow')}</button>`,'i-shield'));}
$('#run-agent').onclick=toggleRun;$('#prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();toggleRun();}});
$$('[data-prompt]').forEach(el=>el.onclick=()=>{$('#prompt').value=el.dataset.prompt;$('#prompt').focus();});
$$('[data-view]').forEach(el=>el.onclick=()=>switchView(el.dataset.view));$$('[data-go]').forEach(el=>el.onclick=()=>switchView(el.dataset.go));
document.addEventListener('click',e=>{const upgradeButton=e.target.closest('[data-upgrade]');if(upgradeButton)upgrade(Number(upgradeButton.dataset.upgrade));const claim=e.target.closest('[data-claim]');if(claim)claimMission(Number(claim.dataset.claim));if(e.target.closest('[data-close]'))$('#modal').close();});
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close();}});
$('#connect-agent').onclick=agentModal;$('#agent-settings').onclick=agentModal;$('#wallet-configure').onclick=agentModal;
$('#copy-id').onclick=async()=>{try{await navigator.clipboard.writeText('DEMO-00482');toast('Demo agent ID copied.');}catch{toast('Demo agent ID: DEMO-00482');}};
$('#agent-coin').onclick=()=>toast('Your agent does the tapping. Send a prompt in Command center.');
$('#how-it-works').onclick=()=>showModal(modalContent('You prompt. Your agent taps.',`<ol><li><strong>Set up your agent.</strong> Live play will require a Binance AI Agent ID and an agent wallet.</li><li><strong>Send a command.</strong> Try “Tap 100 times.” Your simulated agent uses 1 energy per tap and earns TAP points.</li><li><strong>Build your edge.</strong> Spend points on power, energy, and speed upgrades.</li></ol><p class="modal-note">The demo recognizes tapping and energy commands; it is not connected to an AI model. Points have no monetary value.</p><button class="run-button" data-close>Enter the arena ${icon('i-arrow')}</button>`));
$('#season-info').onclick=()=>showModal(modalContent('Welcome to Genesis.',`<p>Season 01 explores a simple idea: humans direct, agents play. Build your agent, complete missions, and collect demo TAP points.</p><p>Season dates, rewards and token eligibility will be announced when the live game is ready. No airdrop or conversion is guaranteed.</p><button class="run-button" data-close>Let’s get tapping ${icon('i-arrow')}</button>`,'i-cup'));
$('#network-info').onclick=()=>showModal(modalContent('Built with BNB Chain in mind.',`<p>The planned game uses BNB Smart Chain for agent wallets and a future memecoin. This demo does not make blockchain transactions.</p><p class="modal-note">No network switch, gas fees, wallet signature, or token approval is needed to explore.</p><button class="run-button" data-close>Back to the arena ${icon('i-arrow')}</button>`,'i-link'));
$('#conversion-info').onclick=()=>showModal(modalContent('Points today. Possibilities ahead.',`<p>A future token conversion is part of the concept. The memecoin contract, conversion ratio, launch date and eligibility rules have not been set.</p><p>Demo TAP points cannot be withdrawn, traded or converted. They have no monetary value.</p><button class="run-button" data-close>Understood ${icon('i-arrow')}</button>`,'i-coin'));
$('#demo-info').onclick=about;
setInterval(()=>{if(state.energy<state.capacity){state.energy=Math.min(state.capacity,state.energy+5);$('#energy-count').innerHTML=`${fmt(state.energy)} <span>/ ${fmt(state.capacity)}</span>`;$('#energy-bar').style.width=(state.energy/state.capacity*100)+'%';}if(!running)save();},1000);
window.addEventListener('pagehide',()=>{save();});
render();renderLogs();switchView(location.hash.slice(1)||'arena');
